def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_me, last_opp = history[-1]

    # Count moves and scores.
    my_score = 0
    opp_score = 0
    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0

    for me, opp in history:
        if me == 'C':
            my_c += 1
        else:
            my_d += 1
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if me == 'C' and opp == 'C':
            cc += 1
            my_score += 3
            opp_score += 3
        elif me == 'C' and opp == 'D':
            cd += 1
            opp_score += 5
        elif me == 'D' and opp == 'C':
            dc += 1
            my_score += 5
        else:
            dd += 1
            my_score += 1
            opp_score += 1

    remaining = 100 - n

    # Opponent seems unconditionally cooperative: do not punish, and only exploit at the very end.
    if opp_d == 0:
        if remaining <= 3 and n >= 25:
            if remaining == 1:
                return 'D'
            if remaining == 2 and rng.random() < 0.55:
                return 'D'
            if remaining == 3 and rng.random() < 0.35:
                return 'D'
        return 'C'

    # Opponent seems unconditionally defective: minimize losses.
    if opp_c == 0:
        return 'D'

    # Recent opponent behavior.
    recent_len = 10 if n >= 10 else n
    recent = history[-recent_len:]
    recent_opp_c = sum(1 for me, opp in recent if opp == 'C')
    recent_opp_d = recent_len - recent_opp_c

    # If opponent's last move was cooperation:
    if last_opp == 'C':
        # If they are generally cooperative, cooperate. This preserves mutual cooperation.
        if opp_d * 5 <= n:
            return 'C'

        # Recent cooperation is high enough: cooperate, with very rare probing only late.
        if recent_opp_c >= 7:
            if remaining <= 2 and n >= 30 and rng.random() < 0.25:
                return 'D'
            return 'C'

        # Mixed opponent. Cooperate unless recent defection pressure is high.
        if recent_opp_d >= 5:
            return 'D'
        if opp_d * 2 > opp_c and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Opponent's last move was defection. Decide whether to retaliate or forgive.
    # Count consecutive opponent defections at the end.
    tail_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            tail_d += 1
        else:
            break

    # Strong, concentrated defection: punish.
    if tail_d >= 3:
        return 'D'

    # If opponent has a strong cooperative record, forgive quickly.
    if opp_c * 4 >= n * 3:
        # After isolated defections, return to cooperation often to avoid collapse.
        if tail_d == 1 and rng.random() < 0.65:
            return 'C'
        if tail_d == 2 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Against moderately cooperative opponents, retaliate but sometimes reset.
    if opp_c * 2 >= n:
        if tail_d == 1 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Otherwise defect defensively.
    return 'D'
